package changelog_test

import (
	"strings"
	"testing"

	"github.com/stricttools/testisolation/go/hygiene"

	"github.com/stricttools/rlsbl/internal/changelog"
	"github.com/stricttools/rlsbl/internal/git"
	"github.com/stricttools/rlsbl/internal/semver"
	"github.com/stricttools/rlsbl/internal/testsupport"
)

// released is a standalone repository whose first commit is release 0.1.0,
// followed by an ordinary commit, an autogenerated one, and one touching
// only the changelog.
type released struct {
	repo          *testsupport.Repo
	release       string
	change        string
	autogenerated string
	bookkeeping   string
}

func newReleased(t *testing.T) released {
	t.Helper()
	repo := testsupport.NewRepo(t)
	r := released{repo: repo}
	r.release = repo.CommitFile("a.txt", "a\n", "the first release")
	writeArchive(t, repo.Dir, "portal", "0.1.0", "recorded", r.release, "The first release")
	r.change = repo.CommitFile("b.txt", "b\n", "a change")
	r.autogenerated = repo.CommitFile("c.txt", "c\n", "regenerate\n\nAutogenerated: true")
	r.bookkeeping = repo.CommitFile(changelog.Dir("portal")+"/unreleased.jsonl", "", "changelog: bookkeeping")
	return r
}

func TestTheUnreleasedRangeStartsAtTheNearestRelease(t *testing.T) {
	hygiene.Isolate(t)
	r := newReleased(t)
	w := newWorkspace(t, r.repo.Dir, standalone)
	mustNotFail(t, reading(t, r.repo.Dir, func(repo git.Repo) error {
		rng, err := subject(t, repo, w, "portal").UnreleasedRange()
		if err != nil {
			return err
		}
		if rng.Base != r.release || rng.Head != r.bookkeeping {
			t.Errorf("range %s..%s", rng.Base, rng.Head)
		}
		if strings.Join(rng.Commits, ",") != strings.Join([]string{r.bookkeeping, r.autogenerated, r.change}, ",") {
			t.Errorf("commits %v", rng.Commits)
		}
		if rng.Contains(r.release) || !rng.Contains(r.change) {
			t.Error("Contains disagrees with the commits")
		}
		return nil
	}))
}

func TestWithoutAReleaseEveryCommitIsUnreleased(t *testing.T) {
	hygiene.Isolate(t)
	repo := testsupport.NewRepo(t)
	first := repo.CommitFile("a.txt", "a\n", "first")
	w := newWorkspace(t, repo.Dir, standalone)
	mustNotFail(t, reading(t, repo.Dir, func(gr git.Repo) error {
		rng, err := subject(t, gr, w, "portal").UnreleasedRange()
		if err != nil {
			return err
		}
		if rng.Base != "" || strings.Join(rng.Commits, ",") != first {
			t.Errorf("range %+v", rng)
		}
		return nil
	}))
}

func TestAForkLeavesItsUpstreamHistoryOutOfTheRange(t *testing.T) {
	hygiene.Isolate(t)
	repo := testsupport.NewRepo(t)
	inherited := repo.CommitFile("a.txt", "a\n", "upstream's commit")
	repo.Git("update-ref", "refs/upstream/example.com/owner/portal/main", inherited)
	own := repo.CommitFile("b.txt", "b\n", "the fork's commit")
	w := newWorkspace(t, repo.Dir, standalone)
	mustNotFail(t, reading(t, repo.Dir, func(gr git.Repo) error {
		s, err := changelog.NewSubject(gr, w, "portal", "https://example.com/owner/portal", []string{"refs/upstream/example.com/owner/portal/main"})
		if err != nil {
			return err
		}
		rng, err := s.UnreleasedRange()
		if err != nil {
			return err
		}
		if strings.Join(rng.Commits, ",") != own {
			t.Errorf("commits %v", rng.Commits)
		}
		return nil
	}))
}

func TestCoverageAsksForTheCommitsThatAreNeitherCoveredNorExempt(t *testing.T) {
	hygiene.Isolate(t)
	r := newReleased(t)
	w := newWorkspace(t, r.repo.Dir, standalone)
	mustNotFail(t, reading(t, r.repo.Dir, func(repo git.Repo) error {
		s := subject(t, repo, w, "portal")
		rng, err := s.UnreleasedRange()
		if err != nil {
			return err
		}
		empty := &changelog.File{Path: s.Dir() + "/unreleased.jsonl"}
		c, err := s.CoverageOf(empty, rng)
		if err != nil {
			return err
		}
		if strings.Join(c.Uncovered, ",") != r.change || c.Stats.Autogenerated != 1 || c.Stats.ChangelogOnly != 1 {
			t.Errorf("coverage %+v", c)
		}
		requireContains(t, strings.Join(c.Findings(), "\n"), "not covered by any changelog entry: "+r.change[:12])
		requireContains(t, strings.Join(c.Notes(), "\n"), "skipped 1 autogenerated commit(s)", "skipped 1 changelog-only commit(s)")
		covering := &changelog.File{Path: empty.Path, Lines: []changelog.Line{{Number: 1, Entry: feature("1", "A change", r.change[:10])}}}
		c, err = s.CoverageOf(covering, rng)
		if err != nil {
			return err
		}
		if len(c.Uncovered) != 0 {
			t.Errorf("an abbreviated id did not cover its commit: %+v", c)
		}
		return nil
	}))
}

func TestExemptionsAreAskedAutogeneratedFirst(t *testing.T) {
	hygiene.Isolate(t)
	repo := testsupport.NewRepo(t)
	both := repo.CommitFile("CHANGELOG.md", "x\n", "regenerate\n\nAutogenerated: true")
	only := repo.CommitFile(".strictmetadata/releases/portal/v0.1.0.toml", "x\n", "archive")
	plain := repo.CommitFile("src.txt", "x\n", "code")
	repo.Write("src.txt", "z\n")
	repo.Write("CHANGELOG.md", "z\n")
	mixed := repo.Commit("mixed", "src.txt", "CHANGELOG.md")
	mustNotFail(t, reading(t, repo.Dir, func(gr git.Repo) error {
		for sha, want := range map[string]changelog.Exemption{both: changelog.ExemptAutogenerated, only: changelog.ExemptChangelogOnly, plain: "", mixed: ""} {
			got, err := changelog.ExemptionOf(gr, sha)
			if err != nil {
				return err
			}
			if got != want {
				t.Errorf("%s: %q, want %q", sha[:7], got, want)
			}
		}
		kept, stats, err := changelog.FilterExempt(gr, []string{both, only, plain})
		if err != nil {
			return err
		}
		if strings.Join(kept, ",") != plain || stats.Autogenerated != 1 || stats.ChangelogOnly != 1 {
			t.Errorf("kept %v, stats %+v", kept, stats)
		}
		return nil
	}))
}

func TestHashFindingsNameEachCommitThatDoesNotResolve(t *testing.T) {
	hygiene.Isolate(t)
	r := newReleased(t)
	w := newWorkspace(t, r.repo.Dir, standalone)
	mustNotFail(t, reading(t, r.repo.Dir, func(repo git.Repo) error {
		s := subject(t, repo, w, "portal")
		f := &changelog.File{Path: s.Dir() + "/unreleased.jsonl", Lines: []changelog.Line{{Number: 2, Entry: feature("1", "d", r.change, "deadbeefdead")}}}
		findings, err := s.HashFindings(f)
		if err != nil {
			return err
		}
		if len(findings) != 1 {
			t.Fatalf("findings %v", findings)
		}
		requireContains(t, findings[0], "line 2 of .strictmetadata/changelog/portal/unreleased.jsonl", "deadbeefdead does not resolve", "1 of 2 commits")
		return nil
	}))
}

func TestARangeFindingSaysWhetherACommitShippedOrBelongsElsewhere(t *testing.T) {
	hygiene.Isolate(t)
	r := newReleased(t)
	w := newWorkspace(t, r.repo.Dir, standalone)
	mustNotFail(t, reading(t, r.repo.Dir, func(repo git.Repo) error {
		s := subject(t, repo, w, "portal")
		rng, err := s.UnreleasedRange()
		if err != nil {
			return err
		}
		f := &changelog.File{Path: s.Dir() + "/unreleased.jsonl", Lines: []changelog.Line{{Number: 1, Entry: feature("1", "d", r.release, r.change)}}}
		findings, err := s.RangeFindings(f, rng)
		if err != nil {
			return err
		}
		if len(findings) != 1 {
			t.Fatalf("findings %v", findings)
		}
		requireContains(t, findings[0], r.release, "not in the unreleased range", "not between the nearest release and HEAD")
		return nil
	}))

	repo := testsupport.NewRepo(t)
	widget := repo.CommitFile("widget/w.txt", "w\n", "widget work")
	gadget := repo.CommitFile("gadget/g.txt", "g\n", "gadget work")
	ws := newWorkspace(t, repo.Dir, twoReleasables)
	mustNotFail(t, reading(t, repo.Dir, func(gr git.Repo) error {
		s := subject(t, gr, ws, "widget")
		rng, err := s.UnreleasedRange()
		if err != nil {
			return err
		}
		f := &changelog.File{Path: s.Dir() + "/unreleased.jsonl", Lines: []changelog.Line{{Number: 1, Entry: feature("1", "d", widget, gadget)}}}
		findings, err := s.RangeFindings(f, rng)
		if err != nil {
			return err
		}
		if len(findings) != 1 {
			t.Fatalf("findings %v", findings)
		}
		requireContains(t, findings[0], gadget, "outside this changelog's scope", `member "gadget" (releasable "gadget")`, "filed under the wrong releasable", "rlsbl changelog remove --id "+id("1"))
		return nil
	}))
}

