func TestAnEntryWithNoLiveCommitIsAnOrphan(t *testing.T) {
	hygiene.Isolate(t)
	r := newReleased(t)
	w := newWorkspace(t, r.repo.Dir, standalone)
	mustNotFail(t, reading(t, r.repo.Dir, func(repo git.Repo) error {
		s := subject(t, repo, w, "portal")
		rng, err := s.UnreleasedRange()
		if err != nil {
			return err
		}
		f := &changelog.File{Path: s.Dir() + "/unreleased.jsonl", Lines: []changelog.Line{
			{Number: 1, Entry: feature("1", "live", r.change, "deadbeefdead")},
			{Number: 2, Entry: feature("2", "stale", r.release, "deadbeefdead")},
		}}
		findings, err := s.OrphanFindings(f, rng)
		if err != nil {
			return err
		}
		if len(findings) != 1 {
			t.Fatalf("findings %v", findings)
		}
		requireContains(t, findings[0], "line 2", "1 unresolvable, 1 out of range", "rlsbl changelog remap", "rlsbl changelog remove --id "+id("2"))
		return nil
	}))
}

func TestTheBatchLimits(t *testing.T) {
	hygiene.Isolate(t)
	var six []string
	for i := 0; i < 6; i++ {
		six = append(six, strings.Repeat(string(rune('a'+i)), 40))
	}
	over := feature("1", "big", six...)
	reasoned := over
	reasoned.ID, reasoned.BatchReason = id("2"), "one change"
	f := &changelog.File{Path: "unreleased.jsonl", Lines: []changelog.Line{{Number: 1, Entry: over}, {Number: 2, Entry: reasoned}}}
	findings := changelog.BatchCommitFindings(f)
	if len(findings) != 1 {
		t.Fatalf("findings %v", findings)
	}
	requireContains(t, findings[0], "line 1", "6 commits", "limit of 5", "rlsbl changelog remove --id "+id("1"), "--batch-reason")

	var lines []changelog.Line
	for i := 0; i < 6; i++ {
		lines = append(lines, changelog.Line{Number: i + 1, Entry: internalEntry(string(rune('a'+i)), sha1)})
	}
	files := []*changelog.File{{Path: "unreleased.jsonl", Lines: lines[:3]}, {Path: "1.0.0.jsonl", Released: true, Lines: lines[3:]}}
	entryFindings := changelog.BatchEntryFindings(files)
	if len(entryFindings) != 1 {
		t.Fatalf("entry findings %v", entryFindings)
	}
	requireContains(t, entryFindings[0], sha1[:12], "6 changelog entries", "unreleased.jsonl:1", "1.0.0.jsonl:6")
	files[1].Lines = lines[3:5]
	if got := changelog.BatchEntryFindings(files); len(got) != 0 {
		t.Errorf("five entries per commit were refused: %v", got)
	}
}

func TestTheReleasesRuleOnUserFacingEntries(t *testing.T) {
	hygiene.Isolate(t)
	user := []changelog.Entry{feature("1", "d", sha1)}
	internal := []changelog.Entry{internalEntry("2", sha1)}
	if p := changelog.UserFacingProblem(user, semver.Infra); !strings.Contains(p, "infra release must not") {
		t.Errorf("infra with a user-facing entry: %q", p)
	}
	if p := changelog.UserFacingProblem(internal, semver.Infra); p != "" {
		t.Errorf("infra without: %q", p)
	}
	if p := changelog.UserFacingProblem(internal, semver.Patch); !strings.Contains(p, "a patch release needs at least one user-facing") {
		t.Errorf("patch without: %q", p)
	}
	if p := changelog.UserFacingProblem(user, semver.Minor); p != "" {
		t.Errorf("minor with: %q", p)
	}
	if changelog.HasUserFacing(internal) || !changelog.HasUserFacing(user) {
		t.Error("HasUserFacing")
	}
}
